//! Shared CanonicalV1 parity corpus generated by the Runtime `canonical` CLI.
//!
//! `vectors/canonical-v1-parity.json` is copied unchanged from the COS Runtime
//! (`contract-core` `tests/vectors/canonical-v1-parity.json`); the Runtime owns
//! every expected value and the Desktop never edits them. The corpus pins the
//! S1-REPAIR findings:
//!
//! - B-01: integers beyond `u64::MAX` / below `i64::MIN` stay verbatim decimal
//!   integers (`serde_json` arbitrary precision on both sides), never floats,
//! - B-02: NFC boundaries on the pinned `unicode-normalization = 0.1.22` tables
//!   (U+212B and A+U+030A to U+00C5, U+0958 to U+0915 U+093C) and non-BMP key
//!   ordering by code point (U+E000 before U+1F600),
//! - escaping, null-member removal, nested mixed values and the fail-closed
//!   float / NFC-collision rejections.

use desktop_protocol::canonical_json;
use serde::Deserialize;
use serde_json::Value;

const CORPUS: &str = include_str!("vectors/canonical-v1-parity.json");

/// Every case the S1-REPAIR review requires, in corpus order.
const REQUIRED_CASES: [&str; 8] = [
    "big-u64-overflow",
    "nfc-boundary",
    "supplementary-key-order",
    "escape-boundary",
    "null-rules",
    "nested-mixed",
    "nfc-collision-reject",
    "float-rejected",
];

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Corpus {
    schema_version: u32,
    cases: Vec<CorpusCase>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct CorpusCase {
    name: String,
    input: Value,
    #[serde(default)]
    canonical: Option<String>,
    #[serde(default)]
    rejected: bool,
    #[serde(default)]
    reason_contains: Option<String>,
}

fn corpus() -> Corpus {
    serde_json::from_str(CORPUS).expect("parity corpus parses")
}

fn case<'a>(corpus: &'a Corpus, name: &str) -> &'a CorpusCase {
    corpus
        .cases
        .iter()
        .find(|case| case.name == name)
        .unwrap_or_else(|| panic!("missing corpus case: {name}"))
}

fn expected_canonical(case: &CorpusCase) -> &str {
    case.canonical
        .as_deref()
        .unwrap_or_else(|| panic!("case {} has no canonical member", case.name))
}

fn expected_reason(case: &CorpusCase) -> &str {
    case.reason_contains
        .as_deref()
        .unwrap_or_else(|| panic!("case {} has no reason_contains member", case.name))
}

/// Offset of the first differing byte, or the shared length when one side is a
/// prefix of the other.
fn first_difference(left: &[u8], right: &[u8]) -> usize {
    left.iter()
        .zip(right)
        .position(|(left, right)| left != right)
        .unwrap_or_else(|| left.len().min(right.len()))
}

#[test]
fn corpus_declares_the_reviewed_cases() {
    let corpus = corpus();
    assert_eq!(corpus.schema_version, 1, "corpus schema_version");
    let names: Vec<&str> = corpus.cases.iter().map(|case| case.name.as_str()).collect();
    assert_eq!(names, REQUIRED_CASES, "reviewed cases in order");

    for case in &corpus.cases {
        if case.rejected {
            assert!(
                case.canonical.is_none(),
                "reject case {} must not carry canonical",
                case.name
            );
            assert!(
                case.reason_contains.is_some(),
                "reject case {} must carry reason_contains",
                case.name
            );
        } else {
            assert!(
                case.canonical.is_some(),
                "accept case {} must carry canonical",
                case.name
            );
            assert!(
                case.reason_contains.is_none(),
                "accept case {} must not carry reason_contains",
                case.name
            );
        }
    }
}

#[test]
fn canonical_bytes_match_the_runtime_corpus() {
    let corpus = corpus();
    for case in &corpus.cases {
        if case.rejected {
            let error = canonical_json(&case.input)
                .err()
                .unwrap_or_else(|| panic!("case {} must be rejected", case.name));
            assert!(
                error.to_string().contains(expected_reason(case)),
                "case {} reason: {error}",
                case.name
            );
            continue;
        }
        let desktop = canonical_json(&case.input)
            .unwrap_or_else(|error| panic!("case {} must be canonical: {error}", case.name));
        let runtime = expected_canonical(case);
        if desktop != runtime.as_bytes() {
            let offset = first_difference(&desktop, runtime.as_bytes());
            panic!(
                "case {} canonical disagrees at byte offset {offset}\n\
                 desktop: {:?}\n\
                 runtime: {:?}",
                case.name,
                String::from_utf8_lossy(&desktop),
                runtime,
            );
        }
    }
}

#[test]
fn integers_past_u64_and_i64_bounds_stay_verbatim() {
    let corpus = corpus();
    let canonical = expected_canonical(case(&corpus, "big-u64-overflow"));
    assert!(canonical.contains("18446744073709551616"), "{canonical}");
    assert!(canonical.contains("-18446744073709551616"), "{canonical}");
    // No fraction and no exponent: an f64 path would silently lose the low
    // digits, which is exactly the B-01 parity gap.
    assert!(!canonical.contains('.'), "{canonical}");
    assert!(!canonical.contains('e'), "{canonical}");
    // The Desktop re-derives the same bytes from the parsed value, so a narrow
    // integer parser would fail here rather than round.
    let desktop = canonical_json(&case(&corpus, "big-u64-overflow").input).expect("canonical");
    assert_eq!(String::from_utf8_lossy(&desktop), canonical);
}

#[test]
fn unicode_boundaries_are_nfc_normalised() {
    let corpus = corpus();
    let canonical = expected_canonical(case(&corpus, "nfc-boundary"));
    assert_eq!(
        canonical.matches('\u{00c5}').count(),
        2,
        "A+U+030A and U+212B both NFC to U+00C5: {canonical}"
    );
    assert!(canonical.contains('\u{00e9}'), "{canonical}");
    assert!(
        canonical.contains("\u{0915}\u{093c}"),
        "U+0958 NFC to KA + NUKTA: {canonical}"
    );
    for decomposed in ['\u{0301}', '\u{030a}', '\u{212b}', '\u{0958}'] {
        assert!(
            !canonical.contains(decomposed),
            "decomposed/singleton form survived: U+{:04X}",
            u32::from(decomposed)
        );
    }
    // U+E000 sorts before the non-BMP U+1F600: code point order, not UTF-16.
    let supplementary = expected_canonical(case(&corpus, "supplementary-key-order"));
    assert!(
        supplementary.find('\u{e000}') < supplementary.find('\u{1f600}'),
        "code point order puts U+E000 before U+1F600: {supplementary}"
    );
}
